import React, { useState } from 'react';
import { Button, Tag, Tile } from '@carbon/react';
import { ArrowRight, ChevronDown, ChevronUp, Idea, DeliveryTruck } from '@carbon/icons-react';

const ConsolidationAlerts = ({ alerts }) => {
  const [isOpen, setIsOpen] = useState(false);

  if (!alerts || alerts.length === 0) return null;

  return (
    <div className="mb-8">
      <Tile className="overflow-hidden border-l-4 border-l-orange-500 p-0">
        <div className="flex flex-wrap items-center justify-between gap-4 bg-orange-10 px-5 py-5 sm:px-6">
          <div className="flex items-center gap-4">
            <div className="flex h-12 w-12 flex-shrink-0 items-center justify-center bg-orange-20 text-orange-70">
              <DeliveryTruck size={24} />
            </div>
            <div>
              <div className="flex flex-wrap items-center gap-2">
                <h3 className="cds--type-productive-heading-03 text-slate-900">Smart Branch Consolidation</h3>
                <Tag type="warm-gray" size="sm">Recommendations</Tag>
              </div>
              <p className="cds--type-body-compact-01 mt-1 text-slate-600">
                Optimize routes by combining nearby branch deliveries.
              </p>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <div className="hidden text-right sm:block">
              <p className="cds--type-expressive-heading-03 text-orange-70">{alerts.length}</p>
              <p className="cds--type-label-01 text-slate-600">
                {alerts.length === 1 ? 'Opportunity' : 'Opportunities'}
              </p>
            </div>
            <Button
              kind="tertiary"
              size="md"
              onClick={() => setIsOpen(!isOpen)}
              renderIcon={isOpen ? ChevronUp : ChevronDown}
              iconDescription={isOpen ? 'Hide recommendations' : 'Show recommendations'}
            >
              {isOpen ? 'Hide details' : 'View recommendations'}
            </Button>
          </div>
        </div>

        {isOpen && (
          <div className="border-t border-slate-200 bg-slate-10 p-4 sm:p-5">
            <div className="cds--type-label-01 mb-3 flex items-center gap-2 text-slate-600">
              <Idea size={16} className="text-orange-70" />
              Suggested actions
            </div>
            <ul className="grid gap-3 md:grid-cols-2">
              {alerts.map((alert, index) => (
                <li
                  key={index}
                  className="group list-none"
                >
                  <Tile className="flex h-full items-start gap-3 p-4 transition-shadow group-hover:shadow-md">
                    <span className="flex h-7 w-7 flex-shrink-0 items-center justify-center bg-orange-20 text-xs font-bold text-orange-70">
                      {String(index + 1).padStart(2, '0')}
                    </span>
                    <div className="min-w-0 flex-1">
                      <p className="cds--type-body-compact-01 text-slate-800">{alert}</p>
                      <div className="cds--type-label-01 mt-2 flex items-center gap-1 text-orange-70">
                      Consolidation opportunity
                        <ArrowRight size={14} className="transition-transform group-hover:translate-x-1" />
                      </div>
                    </div>
                  </Tile>
                </li>
              ))}
            </ul>
          </div>
        )}
      </Tile>
    </div>
  );
};

export default ConsolidationAlerts;
